{"packet_id":"D025-02","doc_id":"D025","jurisdiction":"CA","category":"security_deposits","lifecycle":"enacted","title":"Bad faith retention of security deposit damages","requirement":"A landlord or the landlord's successor in interest who in bad faith claims, retains or demands replacement of a security deposit is liable for statutory damages of up to twice the amount of the security, plus actual damages.","key_value":"up to 2x the security","coverage_conditions":"Security deposits governed by this section; applies to landlords and their successors in interest.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":"Statutory damages up to twice the amount of the security in addition to actual damages; court may award bad faith damages whenever warranted, and landlord bears the burden of proof as to reasonableness.","effective_date":null,"citation":"Cal. Civ. Code § 1950.5","quoted_span":"The bad faith claim or retention by a landlord or the landlord’s successors in interest of the security or any portion thereof in violation of this section, or the bad faith demand of replacement of security in violation of subdivision (k), may subject the landlord or the landlord’s successors in interest to statutory damages of up to twice the amount of the security","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D025-02","doc_id":"D025","jurisdiction":"CA","category":"security_deposits","lifecycle":"enacted","title":"Nonrefundable security deposit clause prohibition","requirement":"A lease or rental agreement may not contain a provision characterizing any security deposit as \"nonrefundable.\"","key_value":null,"coverage_conditions":"Any lease or rental agreement; applies to security governed by this section.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Civ. Code § 1950.5","quoted_span":"A lease or rental agreement shall not contain a provision characterizing any security as “nonrefundable.”","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
